  ```rust
  impl YamlMasker {
      fn is_comment_node(n: &tree_sitter::Node) -> bool {
          n.kind() == "comment"
      }

      fn is_scalar_node(n: &tree_sitter::Node) -> bool {
          matches!(
              n.kind(),
              "plain_scalar" | "single_quote_scalar" | "double_quote_scalar" | "block_scalar"
          )
      }
  }

  impl Masker for YamlMasker {
      fn create_mask(&self, source: &[char]) -> Mask {
          let comment_mask =
              TreeSitterMasker::new(self.language, Self::is_comment_node).create_mask(source);
          let scalar_mask =
              TreeSitterMasker::new(self.language, Self::is_scalar_node).create_mask(source);

          let mut spans: Vec<Span<char>> = Vec::new();

          for (span, chars) in comment_mask.iter_allowed(source) {
              let text: String = chars.iter().collect();

              if !is_ignored_comment(&text) {
                  spans.push(span);
              }
          }

          for (span, chars) in scalar_mask.iter_allowed(source) {
              let text: String = chars.iter().collect();

              if crate::yaml_heuristics::is_prose_scalar(&text) {
                  spans.push(span);
              }
          }

          spans.sort_by_key(|s| s.start);
          spans.into_iter().collect()
      }
  }
  ```

  This calls `is_ignored_comment`, a small helper you're extracting
  from `CommentMasker::new`'s existing inline closure (this is a
  reuse cleanup: both maskers should apply the same
  `spellchecker:ignore`-family suppression to comments). Add it once,
  above `CommentMasker`, and update `CommentMasker::new` to use it:

  ```rust
  fn is_ignored_comment(text: &str) -> bool {
      text.contains("spellchecker:ignore")
          || text.contains("spellchecker: ignore")
          || text.contains("spell-checker:ignore")
          || text.contains("spell-checker: ignore")
          || text.contains("spellcheck:ignore")
          || text.contains("spellcheck: ignore")
          || text.contains("harper:ignore")
          || text.contains("harper: ignore")
  }
  ```

  In `CommentMasker::new`, replace the inline
  `Box::new(|text| { text.contains(...) || ... })` closure body with
  `Box::new(|text: &String| is_ignored_comment(text))`.

  Note: `YamlMasker::create_mask` takes `self.language` by value into
  `TreeSitterMasker::new` twice — `tree_sitter::Language` is a cheap,
  `Copy`-able opaque handle, so this is fine and matches how
  `CommentMasker` already passes `language.into()` around.

